document.addEventListener("alpine:init",()=>{class CartItem{constructor(data){this.pid=parseInt(data.pid);this.amount=parseInt(data.amount)||1;this.variation=data.variation}}
Alpine.data("rccart",()=>({items:[],init(){if(RockCommerce.cart)return;RockCommerce.addComponent(this);RockCommerce.cart=this;this.wakeup();this.$watch("items",this.update.bind(this));this.update()},add(data){RockCommerce.trigger("addToCart",data,(data)=>{const item=new CartItem(data);const existingItem=this.items.find((i)=>i.pid===item.pid&&i.variation===item.variation);if(existingItem){existingItem.amount+=item.amount}else{this.items.push(item)}
this.update()})},get count(){let count=0;this.items.forEach((item)=>{count+=parseInt(item.amount||1)});return count},save(){let json=this.sleep();console.log(json,"save to backend")},sleep(){const data={items:this.items,};let json=JSON.stringify(data);localStorage.setItem("rc-cart",json);return json},update(){RockCommerce.debounce("rc-cart-update",()=>{this.updateCartCount();this.sleep()})},updateCartCount(){let elements=document.querySelectorAll("[rc-cart-count]");elements.forEach((el)=>{el.textContent=this.count;if(this.count>0)el.removeAttribute("hidden");else el.setAttribute("hidden",!0)})},wakeup(){const data=localStorage.getItem("rc-cart")||"{}";const parsedData=JSON.parse(data);for(const key in parsedData){if(parsedData.hasOwnProperty(key)){this[key]=parsedData[key]}}},}))})